WITH events AS (SELECT 'ADM:'||hadm_id||':ed' event_id,object_id object_id,'Emergency Department Registered' activity,edregtime timestamp FROM admissions WHERE edregtime IS NOT NULL AND (1=1) UNION ALL SELECT 'ADM:'||hadm_id||':in' event_id,object_id object_id,'Hospital Admitted' activity,admittime timestamp FROM admissions WHERE admittime IS NOT NULL AND (1=1) UNION ALL SELECT 'ADM:'||hadm_id||':auth' event_id,object_id object_id,'Discharge Authorized' activity,discharge_authorized_at timestamp FROM admissions WHERE discharge_authorized_at IS NOT NULL AND (1=1) UNION ALL SELECT 'ADM:'||hadm_id||':out' event_id,object_id object_id,'Hospital Discharged' activity,dischtime timestamp FROM admissions WHERE dischtime IS NOT NULL AND (1=1) UNION ALL SELECT 'OH:'||history_id event_id,object_id object_id,'Order Entered' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='ENTERED') UNION ALL SELECT 'OH:'||history_id event_id,object_id object_id,'Order Reviewed' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='REVIEWED') UNION ALL SELECT 'OH:'||history_id event_id,object_id object_id,'Order Cancelled' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='CANCELLED') UNION ALL SELECT 'LAB:'||order_id||':received' event_id,object_id object_id,'Specimen Received' activity,specimen_received_at timestamp FROM lab_order WHERE specimen_received_at IS NOT NULL AND (1=1) UNION ALL SELECT 'LAB:'||order_id||':verified' event_id,object_id object_id,'Lab Results Verified' activity,results_verified_at timestamp FROM lab_order WHERE results_verified_at IS NOT NULL AND (1=1) UNION ALL SELECT 'MED:'||order_id||':dispense' event_id,object_id object_id,'Medication Dispensed' activity,dispensed_at timestamp FROM medication_order WHERE dispensed_at IS NOT NULL AND (1=1) UNION ALL SELECT 'MED:'||order_id||':stop' event_id,object_id object_id,'Medication Stopped' activity,stopped_at timestamp FROM medication_order WHERE stopped_at IS NOT NULL AND (1=1) UNION ALL SELECT 'PROC:'||order_id||':prep' event_id,object_id object_id,'Procedure Preparation Completed' activity,preparation_completed_at timestamp FROM procedure_order WHERE preparation_completed_at IS NOT NULL AND (1=1) UNION ALL SELECT 'LABEV:'||e.labevent_id||':chart' event_id,o.object_id object_id,'Lab Measurement Charted' activity,e.charttime timestamp FROM labevents e JOIN lab_order o ON o.order_id=e.order_id WHERE e.charttime IS NOT NULL AND (1=1) UNION ALL SELECT 'LABEV:'||e.labevent_id||':result' event_id,o.object_id object_id,'Lab Result Available' activity,e.storetime timestamp FROM labevents e JOIN lab_order o ON o.order_id=e.order_id WHERE e.storetime IS NOT NULL AND (1=1) UNION ALL SELECT 'EMAR:'||e.emar_id event_id,o.object_id object_id,'Medication Administered' activity,e.charttime timestamp FROM emar e JOIN medication_order o ON o.order_id=e.order_id WHERE e.charttime IS NOT NULL AND (e.event_txt='Administered') UNION ALL SELECT 'EMAR:'||e.emar_id event_id,o.object_id object_id,'Medication Not Given' activity,e.charttime timestamp FROM emar e JOIN medication_order o ON o.order_id=e.order_id WHERE e.charttime IS NOT NULL AND (e.event_txt='Not Given') UNION ALL SELECT 'PROCEV:'||e.procedureevent_id||':start' event_id,o.object_id object_id,'Procedure Started' activity,e.starttime timestamp FROM procedureevents e JOIN procedure_order o ON o.order_id=e.order_id WHERE e.starttime IS NOT NULL AND (1=1) UNION ALL SELECT 'PROCEV:'||e.procedureevent_id||':end' event_id,o.object_id object_id,'Procedure Completed' activity,e.endtime timestamp FROM procedureevents e JOIN procedure_order o ON o.order_id=e.order_id WHERE e.endtime IS NOT NULL AND (1=1)), attributed AS (SELECT e.*,a.object_id admission_object,p.object_id patient_object FROM events e LEFT JOIN clinical_order c ON c.object_id=e.object_id JOIN admissions a ON a.object_id=e.object_id OR a.hadm_id=c.hadm_id JOIN patients p ON p.subject_id=a.subject_id) SELECT e.event_id,e.object_id case_id,e.activity,e.timestamp FROM attributed e JOIN object o ON o.object_id=e.object_id LEFT JOIN clinical_order c ON c.object_id=o.object_id WHERE o.type_code='CLINICAL_ORDER' AND c.order_kind='PROC' AND e.activity IN ('Procedure Preparation Completed','Procedure Started','Procedure Completed') ORDER BY case_id,timestamp,event_id;
